"""Strict, incremental decoder for HTTP/1.1 chunked transfer coding.

Implements the grammar:

    chunk          = chunk-size [ ";" ext-name "=" ext-value ]* CRLF
                     chunk-data CRLF
    last-chunk     = *("0") [ chunk-ext ] CRLF
    trailer-part   = *( header-field CRLF )
    chunked-body   = *chunk last-chunk trailer-section CRLF

Extensions are parsed (so malformed syntax there still surfaces as a size
error) but otherwise ignored. Trailers are consumed and discarded.

Strictness violations raise ChunkError subclasses describing what was wrong:
non-hex size characters, chunk data not terminated by CRLF, or any input
fed after the body has completed.
"""

from __future__ import annotations

CRLF = b"\r\n"
_HEX_DIGITS = set(b"0123456789abcdefABCDEF")


class ChunkError(Exception):
    """Base class for all chunked-decoding violations."""


class InvalidChunkSizeError(ChunkError):
    """A chunk-size line contained non-hex characters or was malformed."""


class ChunkDataNotTerminatedError(ChunkError):
    """Chunk data was not immediately followed by CRLF."""


class InputAfterFinishedError(ChunkError):
    """Bytes were fed to the decoder after the message was complete."""


# Parser states
_SIZE, _DATA, _TRAILERS, _DONE = range(4)


class ChunkedDecoder:
    """Incremental chunked transfer-encoding decoder.

    Feed arbitrary byte fragments with ``feed()``; it returns the decoded
    body accumulated so far. ``finished`` becomes True once the zero-size
    chunk, trailers, and final CRLF have all been seen.
    """

    MAX_LINE = 65536  # sanity cap for size/trailer lines

    def __init__(self) -> None:
        self._buf = bytearray()
        self._state = _SIZE
        self._remaining = 0
        self._body = bytearray()
        self._done = False

    # ------------------------------------------------------------------ API

    @property
    def finished(self) -> bool:
        """True once the terminating chunk, trailers, and final CRLF are seen."""
        return self._done

    def feed(self, data: bytes) -> bytes:
        """Consume a fragment of the wire stream; return decoded body so far."""
        if self._done:
            raise InputAfterFinishedError(
                "input fed after chunked body already complete"
            )
        self._buf += data
        self._parse()
        return bytes(self._body)

    # ------------------------------------------------------------- internals

    def _parse(self) -> None:
        while True:
            if self._state == _SIZE:
                if not self._read_size_line():
                    return
            elif self._state == _DATA:
                if not self._read_chunk_data():
                    return
            elif self._state == _TRAILERS:
                if not self._read_trailers():
                    return
            else:  # _DONE
                if self._buf:
                    raise InputAfterFinishedError(
                        f"{len(self._buf)} trailing byte(s) after final CRLF"
                    )
                return

    def _read_size_line(self) -> bool:
        idx = self._buf.find(CRLF)
        if idx == -1:
            lf = self._buf.find(b"\n")
            if lf != -1:
                raise InvalidChunkSizeError(
                    "chunk-size line uses bare LF instead of CRLF"
                )
            if len(self._buf) > self.MAX_LINE:
                raise InvalidChunkSizeError("chunk-size line exceeds maximum length")
            return False  # need more data
        line = bytes(self._buf[:idx])
        del self._buf[: idx + 2]

        size_part, _, ext = line.partition(b";")
        size_token = size_part.strip()
        if not size_token:
            raise InvalidChunkSizeError(f"empty chunk-size in line {line!r}")
        if not set(size_token) <= _HEX_DIGITS:
            bad = sorted(set(size_token) - _HEX_DIGITS)
            raise InvalidChunkSizeError(
                f"non-hex character(s) {bad!r} in chunk size {size_token!r}"
            )
        # Extension part deliberately ignored beyond being syntactically
        # separated from the size token.
        del ext

        size = int(size_token, 16)
        if size == 0:
            self._state = _TRAILERS
        else:
            self._remaining = size
            self._state = _DATA
        return True

    def _read_chunk_data(self) -> bool:
        need = self._remaining + 2
        if len(self._buf) < need:
            return False  # need more data
        terminator = bytes(self._buf[self._remaining : need])
        if terminator != CRLF:
            raise ChunkDataNotTerminatedError(
                f"chunk data of length {self._remaining} not followed by "
                f"CRLF (got {terminator!r})"
            )
        self._body += self._buf[: self._remaining]
        del self._buf[:need]
        self._remaining = 0
        self._state = _SIZE
        return True

    def _read_trailers(self) -> bool:
        while True:
            idx = self._buf.find(CRLF)
            if idx == -1:
                if len(self._buf) > self.MAX_LINE:
                    raise ChunkError("trailer line exceeds maximum length")
                return False  # need more data
            line = bytes(self._buf[:idx])
            del self._buf[: idx + 2]
            if line == b"":
                # Final CRLF terminating the trailer section.
                self._state = _DONE
                self._done = True
                if self._buf:
                    raise InputAfterFinishedError(
                        f"{len(self._buf)} trailing byte(s) after final CRLF"
                    )
                return False  # fully done; _parse will stop at _DONE
            # Trailer header field: consumed and discarded.

